<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useSessionStore} from '@/stores/session'
import {useServiceContext} from '@/composables/useServiceContext'
import {asApiError,requestBytes} from '@/api/client'
import {capabilities,directoryStatus,isDirectoryRecord,isPage,query,type Json} from '@/api/modules/clientServices'
import {isArtistCatalogItem,type ArtistCatalogItem} from '@/api/modules/artists'
import {validSupplyId,type SupplyAsset} from '@/api/modules/supply'
import ServiceWorkspace from '@/components/ServiceWorkspace.vue'
import PrivateAssetPicker from '@/components/PrivateAssetPicker.vue'
const route=useRoute(),router=useRouter(),operator=computed(()=>route.meta.directoryOperator===true),newFeature=computed(()=>route.meta.directoryView==='feature-new'),newProfile=computed(()=>route.meta.directoryView==='profile-new'),creating=computed(()=>newFeature.value||newProfile.value),kind=computed(()=>String(route.params.kind||'ORGANIZATION')),id=computed(()=>String(route.params.recordId||''))
const session=useSessionStore(),ui=useServiceContext(()=>operator.value?null:session.selectedId||null,()=>creating.value&&!!(form.display_name||form.introduction||form.city||form.recommendation||form.listing_id||form.valid_from||form.valid_until||evidence.value.length||cover.value.length)||!!reason.value,()=>uploadLocked.value||coverLocked.value),{error,notice,busy,pending}=ui
const records=ref<Json[]>([]),record=ref<Json|null>(null),cursor=ref<string|number|null>(null),loading=ref(false),cover=ref<SupplyAsset[]>([]),evidence=ref<SupplyAsset[]>([]),uploadLocked=ref(false),coverLocked=ref(false),reason=ref(''),checks=ref<string[]>([]),artists=ref<ArtistCatalogItem[]>([]),artistCursor=ref<string|number|null>(null)
const form=reactive({display_name:'',introduction:'',city:'',capabilities:[] as string[],valid_from:'',valid_until:'',listing_id:'',recommendation:'',sort_order:0})
const locked=computed(()=>busy.value||!!pending.value||uploadLocked.value||coverLocked.value)
const owner=computed(()=>session.selected?.party.kind==='ORGANIZATION'&&!['CLOSED','SUSPENDED'].includes(session.selected.party.current_status)&&session.selected.membership.current_status==='ACTIVE'&&session.selected.membership.roles.includes('OWNER'))
const activeCapabilities=computed(()=>session.selected?.party.capabilities.filter(c=>c.current_status==='ACTIVE')||[])
const reviewChecks=computed(()=>record.value?.kind==='FEATURED_ARTIST'?{public_source_verified:'已核对有效公开艺人来源',recommendation_reviewed:'已核对推荐文字',not_star_certification:'已确认这是运营推荐，不是明星认证'}:{identity_verified:'已核对机构身份',capabilities_verified:'已核对有效经营能力',materials_reviewed:'已读取证明材料',public_display_authorized:'已确认公开展示授权',no_private_contact:'公开资料不包含私人联系方式'})
const payload=computed(()=>{const from=Date.parse(form.valid_from),until=Date.parse(form.valid_until);if(!Number.isFinite(from)||!Number.isFinite(until)||until<=from)return null;const period={valid_from:new Date(from).toISOString(),valid_until:new Date(until).toISOString()};if(newFeature.value)return validSupplyId(form.listing_id)&&artists.value.some(a=>a.listing_id===form.listing_id)&&form.recommendation.trim()?{feature:{listing_id:form.listing_id,recommendation:form.recommendation.trim(),sort_order:form.sort_order,...period}}:null;return form.display_name.trim()&&form.introduction.trim()&&form.city.trim()&&evidence.value.length?{profile:{display_name:form.display_name.trim(),introduction:form.introduction.trim(),city:form.city.trim(),capabilities:form.capabilities,cover_asset_id:cover.value[0]?.id||null,evidence_asset_ids:evidence.value.map(a=>a.id),...period}}:null})
const materialIds=computed<string[]>(()=>record.value?.kind==='ORGANIZATION'?[record.value.data.profile.cover_asset_id,...record.value.data.profile.evidence_asset_ids].filter(Boolean):[])
let initialized=false
function initialize(){initialized=true;void load()}
let seq=0
function reset(){seq++;records.value=[];record.value=null;cursor.value=null;loading.value=false;cover.value=[];evidence.value=[];uploadLocked.value=coverLocked.value=false;reason.value='';checks.value=[];artists.value=[];artistCursor.value=null;Object.assign(form,{display_name:'',introduction:'',city:'',capabilities:[],valid_from:'',valid_until:'',listing_id:'',recommendation:'',sort_order:0})}
async function load(more=false){error.value=null;if(!ui.ready.value||loading.value||!operator.value&&!owner.value)return;const n=++seq;loading.value=true;if(creating.value){if(newFeature.value)await loadArtists();loading.value=false;return}if(id.value){record.value=null;const target=id.value,r=await ui.read('/directory/records/'+target,(v):v is Json=>isDirectoryRecord(v)&&v.id===target);if(n!==seq)return;record.value=r;checks.value=[];loading.value=false;return}const old=more?cursor.value:null;if(!more){records.value=[];cursor.value=null}const r=await ui.read('/directory/records'+query({kind:kind.value,cursor:old,limit:20}),isPage((v):v is Json=>isDirectoryRecord(v)&&(operator.value||v.owner_party_id===session.selectedId)));if(n!==seq)return;if(r){if(old!==null&&r.next_cursor===old)ui.fail('记录分页未更新，请刷新列表。');else{records.value=more?[...records.value,...r.items]:r.items;cursor.value=r.next_cursor}}loading.value=false}
async function loadArtists(more=false){const old=more?artistCursor.value:null,r=await ui.read('/artists/catalog'+query({cursor:old,limit:20}),isPage(isArtistCatalogItem));if(r){if(old!==null&&old===r.next_cursor){ui.fail('公开艺人分页未更新。');return}artists.value=more?[...artists.value,...r.items]:r.items;artistCursor.value=r.next_cursor}}
function recordPath(r:Json){return operator.value?`/directory/reviews/${r.kind}/${r.id}`:`/directory/manage/${r.id}`}
async function submit(){if(locked.value||!payload.value||!operator.value&&!owner.value)return;await ui.write(newFeature.value?'/directory/featured-artists':'/directory/organization-profiles',payload.value,(v):v is Json=>isDirectoryRecord(v)&&v.kind===(newFeature.value?'FEATURED_ARTIST':'ORGANIZATION')&&(newFeature.value||v.owner_party_id===session.selectedId),async r=>{notice.value='已提交，等待独立审核；当前尚未公开。';reset();await router.push(recordPath(r))})}
async function act(action:'APPROVE'|'REJECT'|'WITHDRAW'){const r=record.value;if(!r||locked.value||!reason.value.trim())return;if(action==='APPROVE'&&checks.value.length!==Object.keys(reviewChecks.value).length)return;const body=action==='WITHDRAW'?{reason:reason.value.trim()}:{decision:action,reason:reason.value.trim(),checks:action==='APPROVE'?Object.fromEntries(checks.value.map(k=>[k,true])):null};await ui.write(`/directory/records/${r.id}/${action==='WITHDRAW'?'withdrawals':'reviews'}`,body,(v):v is Json=>isDirectoryRecord(v)&&v.id===r.id,async()=>{reason.value='';checks.value=[];await load()},{ifMatch:r.object_version});if(error.value?.status===412)await load()}
async function download(asset:string){const r=record.value;if(!r)return;const sig=ui.signature.value;try{const blob=await requestBytes(`/directory/records/${r.id}/materials/${asset}`,{token:session.token,actingParty:operator.value?null:session.selectedId});if(sig!==ui.signature.value)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='机构材料-'+asset;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(sig===ui.signature.value){error.value=asApiError(e);if([403,404,409].includes(error.value.status))record.value=null}}}
watch(ui.revision,()=>{reset();if(initialized&&ui.ready.value)void load()},{flush:'sync'})
</script>
<template><ServiceWorkspace :title="newFeature?'提出精选艺人':newProfile?'提交机构公开资料':operator?'目录独立审核':'本机构公开资料'" intro="申请经独立审核后才公开；公开介绍不授予新的经营能力。" :account-only="operator" :dirty="creating&&!!(form.display_name||form.introduction||form.city||form.recommendation||form.listing_id||form.valid_from||form.valid_until||evidence.length||cover.length)||!!reason" :locked="locked" :error="error" :notice="notice" @ready="initialize"><div class="service-tabs"><RouterLink to="/directory/manage">本机构申请</RouterLink><RouterLink to="/directory/organizations">公开机构</RouterLink><RouterLink to="/directory/reviews/ORGANIZATION">机构资料审核</RouterLink><RouterLink to="/directory/reviews/FEATURED_ARTIST">精选审核</RouterLink><RouterLink to="/directory/featured/new">提出精选</RouterLink></div><section v-if="pending" class="service-pending"><p>已保留原请求及内容，请先恢复原操作。</p><button class="outline" :disabled="busy" @click="ui.retry">恢复原请求</button></section><p v-if="!operator&&!owner" class="supply-warning">请先选择当前有效机构负责人的身份。普通成员不能代机构提交公开资料。</p><p v-if="loading" role="status">正在读取…</p><form v-if="creating&&(operator||owner)" class="supply-card" @submit.prevent="submit"><fieldset :disabled="busy||!!pending"><div class="service-form"><template v-if="newProfile"><label>公开名称<input v-model="form.display_name" maxlength="120" required></label><label>城市<input v-model="form.city" maxlength="100" required></label><label class="wide">机构公开介绍<textarea v-model="form.introduction" maxlength="2000" rows="5" required/></label><div class="wide"><p>选择当前有效能力</p><label v-for="c in activeCapabilities" :key="c.code" class="service-check"><input v-model="form.capabilities" type="checkbox" :value="c.code">{{capabilities[c.code]}}</label><p v-if="!activeCapabilities.length">本机构当前没有可公开选择的有效能力。</p></div></template><template v-else><label class="wide">选择当前公开艺人<select v-model="form.listing_id" required><option value="">请选择获准公开的资料</option><option v-for="a in artists" :key="a.listing_id" :value="a.listing_id">{{a.display_name}} · {{a.city}}</option></select></label><button v-if="artistCursor" type="button" class="outline" @click="loadArtists(true)">读取更多公开艺人</button><label class="wide">推荐说明<textarea v-model="form.recommendation" maxlength="500" rows="4" required/></label><label>展示顺序<input v-model.number="form.sort_order" type="number" min="0" max="10000" required></label></template><label>有效开始（本地时间）<input v-model="form.valid_from" type="datetime-local" required></label><label>有效结束（本地时间）<input v-model="form.valid_until" type="datetime-local" required></label></div><p class="supply-warning">新版本一经审核通过就替换旧版本。如果有效开始时间在未来，生效前公开页面会暂时没有这份资料。</p><template v-if="newProfile"><h2>机构主图（可选）</h2><PrivateAssetPicker v-model="cover" purpose="WORK_CONTENT" :max="1" :disabled="busy||!!pending" @lock="coverLocked=$event"/><h2>公开资料证明（至少一份）</h2><PrivateAssetPicker v-model="evidence" :disabled="busy||!!pending" @lock="uploadLocked=$event"/></template><button class="primary" :disabled="locked||!payload">提交并等待独立审核</button></fieldset></form><section v-if="!creating&&!record" class="supply-card"><div class="service-actions"><RouterLink v-if="!operator&&owner" to="/directory/manage/new" class="button-link primary">提交新资料或新版本</RouterLink><button class="outline" :disabled="locked||loading" @click="load()">刷新记录</button></div><article v-for="r in records" :key="r.id" class="service-result"><h2>{{r.data.profile?.display_name||r.data.feature?.recommendation||'精选申请'}}</h2><p>{{directoryStatus[r.current_status]}}</p><RouterLink :to="recordPath(r)" class="button-link outline">查看申请与处理</RouterLink></article><p v-if="!records.length&&!cursor&&!loading&&!error">当前没有获准查看的申请。</p><button v-if="cursor" class="outline" :disabled="loading||locked" @click="load(true)">继续读取申请</button></section><section v-if="record" class="supply-card"><h2>{{record.data.profile?.display_name||'精选艺人申请'}}</h2><p class="service-status">{{directoryStatus[record.current_status]}}</p><p class="service-text">{{record.data.profile?.introduction||record.data.feature?.recommendation}}</p><p v-if="record.kind==='ORGANIZATION'">{{record.data.profile.city}} · {{record.data.profile.capabilities.map((c:string)=>capabilities[c]||c).join(' / ')}}</p><RouterLink v-else :to="'/artists/catalog/'+record.data.feature.listing_id" class="button-link outline">核对当前公开艺人</RouterLink><p class="service-muted">有效期 {{new Date((record.data.profile||record.data.feature).valid_from).toLocaleString()}} 至 {{new Date((record.data.profile||record.data.feature).valid_until).toLocaleString()}}</p><p v-if="record.data.review">审核说明：{{record.data.review.reason}}</p><p v-if="record.data.withdrawal_reason">撤回说明：{{record.data.withdrawal_reason}}</p><div class="service-actions"><button v-for="asset in materialIds" :key="asset" class="outline" @click="download(asset)">读取{{asset===record.data.profile.cover_asset_id?'主图':'证明'}} {{asset.slice(0,8)}}</button></div><p class="service-muted">证明仅供本人和获准审核人查看，不会作为公开介绍展示。</p><form v-if="['IN_REVIEW','APPROVED'].includes(record.current_status)" @submit.prevent="act('WITHDRAW')"><fieldset :disabled="locked"><label class="service-field">本次处理说明<textarea v-model="reason" maxlength="2000" rows="4" required/></label><template v-if="operator&&record.current_status==='IN_REVIEW'"><label v-for="(label,key) in reviewChecks" :key="key" class="service-check"><input v-model="checks" type="checkbox" :value="key">{{label}}</label><div class="service-actions"><button type="button" class="primary" :disabled="!reason.trim()||checks.length!==Object.keys(reviewChecks).length" @click="act('APPROVE')">通过独立审核</button><button type="button" class="outline" :disabled="!reason.trim()" @click="act('REJECT')">退回并说明原因</button></div></template><button class="outline" :disabled="!reason.trim()">{{operator?'撤下本资料':'撤回本机构资料'}}</button></fieldset></form><div class="service-actions"><button class="outline" :disabled="locked" @click="load()">重新读取当前状态</button><RouterLink v-if="!operator" to="/directory/manage/new" class="button-link outline">申请新版本</RouterLink></div></section></ServiceWorkspace></template>
